function solve(intervals) {
  const ivs = intervals.map(x => x.slice()).sort((a, b) => a[0] - b[0]);
  const out = [];
  for (const cur of ivs) {
    let merged = false;
    for (const prev of out) {
      if (cur[0] <= prev[1] && prev[0] <= cur[1]) {
        prev[0] = Math.min(prev[0], cur[0]);
        prev[1] = Math.max(prev[1], cur[1]);
        merged = true;
        break;
      }
    }
    if (!merged) out.push(cur.slice());
  }
  return out.sort((a, b) => a[0] - b[0]);
}

function solve(intervals) {
  intervals.sort((a, b) => a[0] - b[0]);
  const out = [intervals[0].slice()];
  for (let i = 1; i < intervals.length; i++) {
    const last = out[out.length - 1];
    if (intervals[i][0] <= last[1]) last[1] = Math.max(last[1], intervals[i][1]);
    else out.push(intervals[i].slice());
  }
  return out;
}

